// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    X_WALLET c;

    function setUp() public {
        c = new X_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, c.MinSum(), type(uint256).max / 2);
        unlockTime = bound(unlockTime, 0, block.timestamp);

        address actor = address(0xBEEF);
        vm.deal(actor, amount);

        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Warp far enough into the future to guarantee the lock has expired.
        vm.warp(block.timestamp + 1 days);

        bool ok;
        vm.prank(actor);
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "Collect should succeed when the external call succeeds");
    }
}
